from pathlib import Path
import subprocess,json
p=Path('.local-data/b02');tid=(p/'tenant-id').read_text()
sql=f"SELECT jsonb_build_object('tenant',(SELECT jsonb_build_object('id',id,'code',code,'name',name,'status',status,'initialized',initialized,'version',version::text,'staffCount',(SELECT count(*) FROM public.identity_employee e WHERE e.tenant_id=t.id),'storeCount',(SELECT count(*) FROM public.platform_store s WHERE s.tenant_id=t.id)) FROM public.platform_tenant t WHERE id='{tid}'),'accounts',(SELECT jsonb_agg(jsonb_build_object('id',id,'loginName',login_name,'displayName',display_name,'status',status,'version',version::text,'permissions',(SELECT jsonb_agg(permission_code ORDER BY permission_code) FROM pet_control.platform_permission WHERE account_id=a.id)) ORDER BY login_name) FROM pet_control.platform_account a),'platformCleanupPending',(SELECT count(*) FROM pet_control.platform_session_cleanup WHERE NOT completed),'platformCleanupRecordCount',(SELECT count(*) FROM pet_control.platform_session_cleanup),'managementEvents',(SELECT jsonb_agg(jsonb_build_object('operation',operation,'count',n)) FROM (SELECT operation,count(*) n FROM pet_control.management_event GROUP BY operation ORDER BY operation) q),'organization',(SELECT jsonb_agg(jsonb_build_object('code',code,'name',name,'status',status,'version',version::text)) FROM public.identity_organization WHERE tenant_id='{tid}'),'customerIdentityCount',(SELECT count(*) FROM public.customer_subject),'runtimeRestricted',(SELECT NOT(rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb) AND NOT pg_has_role('b02_runtime','pet_control_manager_owner','MEMBER') FROM pg_roles WHERE rolname='b02_runtime'));"
r=subprocess.run(['docker','exec','-i','pet-b02-pg','psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U','postgres','-d','b02_acceptance'],input=sql,text=True,capture_output=True);assert r.returncode==0
value=json.loads(r.stdout);assert value['tenant']['initialized'] and value['tenant']['status']=='ACTIVE' and value['tenant']['staffCount']==1 and value['tenant']['storeCount']==1;assert value['customerIdentityCount']==1 and value['runtimeRestricted'];assert value['platformCleanupPending']==0
states={a['loginName']:a['status'] for a in value['accounts']};assert states=={'b02-platform':'ACTIVE','b02-reader':'DISABLED'}
Path('docs/testing/evidence/B02/completion/final-database.json').write_text(json.dumps({'exitCode':0,'source':'只读观察正式页面/CLI已提交状态，不是SQL准备；不读取秘密或内部安全版本','snapshot':value},ensure_ascii=False,indent=2));print({'status':'PASS','customerIdentityCount':1,'accountStates':states})
